const incoming = $input.first()?.json ?? {};
let body = incoming.body ?? incoming;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch { throw new Error('El body debe ser JSON válido.'); }
}
if (!body || typeof body !== 'object' || Array.isArray(body)) throw new Error('El body debe ser un objeto JSON.');
const direction = String(body.direction ?? 'both').toLowerCase();
if (!['inbound', 'sent', 'both'].includes(direction)) throw new Error('direction debe ser inbound, sent o both.');
const clean = (value, max = 180) => {
  if (value === undefined || value === null) return '';
  if (typeof value !== 'string' && typeof value !== 'number') throw new Error('Los filtros deben ser texto.');
  return String(value).replace(/[\u0000-\u001f\u007f]/g, ' ').trim().slice(0, max);
};
const isoDate = (value, name) => {
  const v = clean(value, 10);
  if (!v) return '';
  if (!/^\d{4}-\d{2}-\d{2}$/.test(v) || Number.isNaN(Date.parse(v + 'T00:00:00Z'))) throw new Error(name + ' debe usar YYYY-MM-DD.');
  return v;
};
const filters = {
  text: clean(body.query ?? body.text, 180),
  contact_email: clean(body.contact_email, 180),
  from: clean(body.from, 180),
  to: clean(body.to, 180),
  subject: clean(body.subject, 180),
  since: isoDate(body.after ?? body.since, 'after'),
  before: isoDate(body.before, 'before'),
};
if (!Object.values(filters).some(Boolean)) throw new Error('Incluye al menos un filtro: query, from, to, subject, after o before.');
if (filters.since && filters.before && filters.since > filters.before) throw new Error('after no puede ser posterior a before.');
const limit = Math.max(1, Math.min(10, Number.parseInt(body.limit ?? 5, 10) || 5));
return [{ json: { direction, filters, limit } }];

const req = $('Validar y preparar filtros').first().json;
const mailbox = 'INBOX';
if (req.direction === 'sent') return [];
const plain = (s) => String(s ?? '').replace(/<\/(p|div|li|tr|br|h[1-6])\s*>/gi, '\n').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&quot;/gi, '"').replace(/&#39;/gi, "'").replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
const address = (v) => { if (Array.isArray(v)) return v.map(address).filter(Boolean); if (typeof v === 'string') return v; if (v && typeof v === 'object') { if (Array.isArray(v.value)) return v.value.map(x => [x.name, x.address].filter(Boolean).join(' ')).join(', '); return [v.name, v.address].filter(Boolean).join(' '); } return ''; };
return $input.all().map(({json}) => ({json:{mailbox, uid:json.uid ?? json.emailUid ?? null, message_id:json.messageId ?? json.message_id ?? null, date:json.date ?? null, subject:json.subject ?? '(sin asunto)', from:address(json.from), to:address(json.to), attachments:Array.isArray(json.attachments) ? json.attachments.map(a => ({name:a.filename ?? a.name ?? null,mime_type:a.contentType ?? a.mimeType ?? null,size:a.size ?? null})) : [], excerpt:plain(json.text || json.textPlain || json.html || json.textHtml).slice(0,700)}})).filter(x => x.json.uid || x.json.message_id);

