const req = $('Validar y preparar filtros').first().json;
const all = $input.all().map(x => x.json).filter(m => m && (m.uid || m.message_id));
all.sort((a,b) => Date.parse(b.date || 0) - Date.parse(a.date || 0));
const seen = new Set();
const unique = all.filter(m => { const k = m.message_id || (m.mailbox + ':' + m.uid); if (seen.has(k)) return false; seen.add(k); return true; });
const results = unique.slice(0, req.limit);
return [{json: {ok: true, direction: req.direction, count: results.length, truncated: unique.length > results.length, results}}];

const req = $('Validar y preparar filtros').first().json;
const mailbox = 'INBOX';
const rows = $input.all().map(x => x.json);
const ids = rows.flatMap(row => Array.isArray(row.uids) ? row.uids : (row.uid != null ? [row.uid] : []))
  .map(uid => String(uid)).filter(uid => /^\d+$/.test(uid));
const unique = [...new Set(ids)].sort((a,b) => Number(b)-Number(a)).slice(0, req.limit);
if (!unique.length) return [{ json: { mailbox, noMatch: true } }];
return unique.map(emailUid => ({ json: { mailbox, emailUid } }));

